styleCss:
#pomi-home-intro-block {
  font-family: Arial, Helvetica, sans-serif;
  color: #2b211d;
  background: #fffaf7;
  line-height: 1.6;
  padding: 72px 0;
}

#pomi-home-intro-block * {
  box-sizing: border-box;
}

#pomi-home-intro-block .pomi-wrap {
  width: min(1120px, 92%);
  margin: 0 auto;
}

#pomi-home-intro-block .pomi-kicker {
  display: inline-block;
  padding: 8px 14px;
  background: #f1d8cc;
  color: #6e3f31;
  border-radius: 999px;
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  margin-bottom: 18px;
}

#pomi-home-intro-block h2 {
  font-size: clamp(30px, 4vw, 46px);
  line-height: 1.12;
  margin: 0 0 16px;
  color: #2b211d;
  text-align: center;
}

#pomi-home-intro-block .pomi-intro {
  max-width: 820px;
  margin: 0 auto 34px;
  text-align: center;
  font-size: 19px;
  color: #4b3c36;
}

#pomi-home-intro-block .pomi-card-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 22px;
  margin-top: 34px;
}

#pomi-home-intro-block .pomi-card {
  background: #ffffff;
  border: 1px solid #efd9cf;
  border-radius: 28px;
  overflow: hidden;
  box-shadow: 0 12px 30px rgba(74, 50, 40, 0.08);
}

#pomi-home-intro-block .pomi-card-image {
  width: 100%;
  height: 255px;
  overflow: hidden;
  background: #f1d8cc;
}

#pomi-home-intro-block .pomi-card-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

#pomi-home-intro-block .pomi-card-body {
  padding: 26px 24px 28px;
  text-align: left;
}

#pomi-home-intro-block h3 {
  font-size: 23px;
  line-height: 1.2;
  margin: 0 0 12px;
  color: #2b211d;
  text-align: left;
}

#pomi-home-intro-block p {
  margin: 0 0 14px;
  font-size: 16px;
  color: #4b3c36;
}

#pomi-home-intro-block ul {
  margin: 0;
  padding-left: 20px;
  color: #4b3c36;
  font-size: 15px;
}

#pomi-home-intro-block li {
  margin-bottom: 7px;
}

#pomi-home-intro-block .pomi-note-box {
  margin-top: 34px;
  background: #fff4ed;
  border: 1px solid #efd9cf;
  border-radius: 30px;
  padding: 30px;
  text-align: center;
}

#pomi-home-intro-block .pomi-note-box p {
  max-width: 850px;
  margin: 0 auto;
  font-size: 17px;
  color: #4b3c36;
}

@media (max-width: 900px) {
  #pomi-home-intro-block .pomi-card-grid {
    grid-template-columns: 1fr;
  }

  #pomi-home-intro-block .pomi-card-image {
    height: 320px;
  }
}

@media (max-width: 560px) {
  #pomi-home-intro-block {
    padding: 52px 0;
  }

  #pomi-home-intro-block .pomi-card-image {
    height: 245px;
  }

  #pomi-home-intro-block .pomi-card-body {
    padding: 22px 20px 24px;
  }
}
